    r.position.x = -0.28;
    bar.add(r);
    const b = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.12, 0.3), new THREE.MeshBasicMaterial({ color: 0x2040ff }));
    b.position.x = 0.28;
    bar.add(b);
    bar.position.set(0, 0.45 + bodyH + 0.62, 0);
