    sign.position.set(0, 0.45 + bodyH + 0.62, 0);
    g.add(sign);
  }

  const wheelGeo = new THREE.CylinderGeometry(0.36, 0.36, 0.28, 14);
  wheelGeo.rotateZ(Math.PI / 2);
